<script setup lang="ts">import {useTripDetailPage} from '../../stores/useTripDetailPage';import {getBearer} from '@kuaixie/sdk';const {prefs,item,loading,unavailable,mobilePreferenceStyle,formatDate,transportLabel,tripAvailability,load}=useTripDetailPage();</script>
<template><view class="app-page detail-page" :class="{'kx-care':prefs.care,'kx-dark':prefs.theme==='dark'}" :style="mobilePreferenceStyle(prefs)"><text class="detail-back" @click="uni.navigateBack()">‹ {{$t('m2.mobile.back')}}</text><view v-if="loading" class="empty-box">{{$t('m2.mobile.loading')}}</view><view v-else-if="unavailable" class="error-box">{{$t('m2.mobile.dataUnavailable')}}<button @click="load">{{$t('m2.catalog.retry')}}</button></view><view v-else-if="!item" class="empty-box">{{$t('fast.notInFirstPage')}}</view><template v-else><view class="trip-banner"><view>{{$t('fast.tripDestination')}}</view><view class="trip-dest">{{item.destination||$t('common.notProvided')}}</view></view><view class="detail-card"><view class="detail-row"><text>{{$t('fast.departDate')}}</text><text>{{formatDate(item.depart_date)}}</text></view><view class="detail-row"><text>{{$t('fast.returnDate')}}</text><text>{{formatDate(item.return_date)}}</text></view><view class="detail-row"><text>{{$t('fast.transport')}}</text><text>{{transportLabel(item.transport_mode)}}</text></view><view class="detail-row"><text>{{$t('fast.entryPort')}}</text><text>{{item.entry_port||$t('common.notProvided')}}</text></view><view class="detail-row"><text>{{$t('fast.capacity')}}</text><text>{{tripAvailability(item)??$t('common.notProvided')}}</text></view><view class="detail-note">{{$t('fast.noTripBooking')}}</view><button class="trip-intent-btn" @click="uni.navigateTo({url:getBearer()?'/pages/create-intent/index?tripId='+encodeURIComponent(String(item.id)):'/pages/login/index?returnPath='+encodeURIComponent('/pages/create-intent/index?tripId='+String(item.id))})">{{$t('v15.createIntent')}}</button></view></template></view></template>
<style scoped>.detail-page{background:#f8fafc;padding:22rpx 28rpx 130rpx}.detail-back{display:block;color:var(--kx-accent,#0ea5e9);padding:16rpx 0}.trip-banner{background:linear-gradient(130deg,var(--kx-accent,#0ea5e9),#38bdf8);padding:45rpx 30rpx;border-radius:21rpx;color:white;font-size:25rpx}.trip-dest{font-size:43rpx;font-weight:750;margin-top:16rpx;overflow-wrap:anywhere}.detail-card{padding:29rpx 25rpx;background:#fff;border:1rpx solid #e2e8f0;border-radius:22rpx;margin-top:19rpx}.detail-row{display:flex;justify-content:space-between;gap:20rpx;padding:19rpx 0;border-bottom:1rpx solid #f1f5f9;font-size:25rpx}.detail-row text:last-child{text-align:right;max-width:65%;overflow-wrap:anywhere}.detail-note{font-size:23rpx;line-height:1.7;padding:19rpx;border-radius:14rpx;background:#f1f5f9;color:#475569;margin-top:28rpx}.kx-dark .detail-card{background:#202629;border-color:#475569}.kx-dark .detail-row{border-color:#39444d} .trip-intent-btn{background:var(--kx-accent,#0ea5e9);color:#fff;border-radius:15rpx;font-size:27rpx;margin-top:24rpx;padding:12rpx 0}</style>
